function renderRoB(){const included=project.rows.filter(r=>r.include),counts={'Low':0,'Some concerns':0,'High':0};included.forEach(r=>counts[r.rob]=(counts[r.rob]||0)+1);const chips=`<span class="rob-chip">Low: ${counts.Low}</span><span class="rob-chip concerns">Some concerns: ${counts['Some concerns']}</span><span class="rob-chip high">High: ${counts.High}</span>`;$('robSummary').innerHTML=chips;$('robDetailed').innerHTML='<div class="rob-summary">'+chips+'</div>'+included.map(r=>`<div class="rob-row"><span>${esc(r.name)} (${esc(r.year||'n.d.')})</span><b>${esc(r.rob)}</b></div>`).join('')+(included.length?'':'<p class="smallprint">Belum ada studi disertakan.</p>')}
