function updateField(e){const field=e.target.dataset.field;if(!field)return;const tr=e.target.closest('tr[data-row]');if(!tr)return;const r=project.rows.find(x=>x.id===tr.dataset.row);if(!r)return;r[field]=['include','verified'].includes(field)?e.target.checked:e.target.value;if(field==='verified'||field==='sourcePaper'||field==='sourcePage'||field==='sourceExcerpt'||field==='name'||field==='year'||field==='group'||field==='rob'||field==='include'||field==='a'||field==='b'||field==='c'||field==='d'||field==='mean1'||field==='sd1'||field==='n1'||field==='mean0'||field==='sd0'||field==='n0'||field==='effect'||field==='se'){clearTimeout(editRenderTimer);editRenderTimer=setTimeout(()=>{renderStudyTable();renderAnalysis()},15)}}
