 for(const line of lines){const cells=[];let cell='',last=null;for(const item of line.parts){if(last&&item.x-(last.x+last.w)>14){if(cell)cells.push(cell.trim());cell=''}else if(last)cell+=' ';cell+=item.t;last=item}if(cell)cells.push(cell.trim());if(cells.length>=3){current.push(cells)}else if(current.length){if(current.length>=3)runs.push(current);current=[]}}
 if(current.length>=3)runs.push(current);
 runs.slice(0,8).forEach((rows,i)=>{if(rows.length<=90)tables.push({page:pageNumber,index:i+1,method:'browser spatial heuristic',rows:rows.slice(0,70).map(x=>x.slice(0,14))})});
 // Pada layout multikolom, rendering source explorer harus selalu dibandingkan PDF asli.
