 for(let i=1;i<=limit;i++){const page=await doc.getPage(i),items=await page.getTextContent(),parsed=reconstructPdfPage(items,i,page.view?.[2]||595);pageData.push({page:i,text:parsed.text});tables.push(...parsed.tables);if(i%5===0){ $('extractStatus').textContent=`${file.name}: ${i}/${limit} halaman` ;await new Promise(r=>setTimeout(r,0))}}
