function populateEvidenceSelect(){const select=$('evidencePaper');if(!select)return;const previous=select.value;select.innerHTML=project.papers.map(p=>`<option value="${attr(p.id)}">${esc(p.filename)} (${p.pages} pages)</option>`).join('');select.value=project.papers.some(p=>p.id===previous)?previous:activePaper||project.papers[0]?.id||'';populateEvidencePages()}
