async function runBackend(files){for(const file of [...files]){if(file.size>25*1024*1024){toast(file.name+': PDF >25MB');continue}try{const base=$('backendUrl').value.replace(/\/+$/,'');if(!/^https?:\/\//.test(base))throw Error('URL backend harus http(s).');if(!/^https?:\/\/(127\.0\.0\.1|localhost)(:\d+)?$/i.test(base)&&!confirm('PDF akan DIKIRIM ke server '+base+'. Gunakan hanya backend milik Anda atau yang dipercaya. Lanjutkan?'))return;const form=new FormData();form.append('file',file);form.append('ocr','true');$('backendStatus').textContent='Python memproses '+file.name+'...';const res=await fetch(base+'/api/extract',{method:'POST',body:form});if(!res.ok)throw Error((await res.text()).slice(0,240));const data=await res.json();const pg=(data.pages||[]).map(x=>({page:x.page,text:x.text||''}));const tbs=data.tables||[];const paper=addPaper(pg.map(x=>x.text).join('\n\n'),file.name,data.page_count||pg.length,{pageData:pg,tables:tbs,engine:'PyMuPDF / OCR',scannedPages:data.ocr_pages||[]});$('backendStatus').textContent=`✓ ${file.name}: ${pg.length} halaman, ${tbs.length} tabel terdeteksi, ${data.ocr_pages?.length||0} halaman OCR.`;showPage('evidence');$('evidencePaper').value=paper.id;populateEvidencePages()}catch(e){$('backendStatus').textContent='Ekstraksi Python gagal: '+e.message;toast('Periksa backend/log server.')}}}
