 $('backupBtn').addEventListener('click',()=>download('ultra-paper-project-backup.json',JSON.stringify(pickProject(),null,2),'application/json'));
 $('restoreBtn').addEventListener('click',()=>$('jsonInput').click());$('jsonInput').addEventListener('change',async e=>{try{if(e.target.files[0]){const obj=JSON.parse(await e.target.files[0].text());if(confirm('Ganti semua data proyek dengan isi file JSON?'))restoreProject(obj)}}catch(err){toast('Restore JSON gagal: '+String(err.message||err))}e.target.value=''});
 $('exportR').addEventListener('click',()=>{const pool=currentPool().pool;if(!pool)return toast('Tambahkan studi valid.');const rows=['study,yi,vi',...pool.rows.map(r=>[r.original.name,r.y,r.v].map(csvCell).join(','))];download('ultra-meta-for-R-metafor.csv','\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8');toast('CSV pada skala analisis siap dibuka di RStudio.');});
 $('pythonCompare').addEventListener('click',async()=>{const pool=currentPool().pool;if(!pool)return toast('Tambahkan studi valid.');$('pythonValidation').textContent='Menghubungi Python untuk verifikasi numerik...';try{const base=$('backendUrl').value.replace(/\/+$/,'');const result=await fetch(base+'/api/meta',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studies:pool.rows.map(r=>({name:r.original.name,yi:r.y,vi:r.v})),model:project.model,inference:project.inference==='HK'?'HK':'normal',level:Number(project.ci)/100})});if(!result.ok)throw Error('HTTP '+result.status);const r=await result.json();const diff=Math.abs(r.mu-pool.mu),seDiff=Math.abs(r.se-pool.se),ciDiff=Math.max(Math.abs(r.ci[0]-pool.ci[0]),Math.abs(r.ci[1]-pool.ci[1]));$('pythonValidation').textContent=`Python ${r.model} (${r.inference}): pooled ${fmt(r.mu,5)}, CI [${fmt(r.ci[0],5)}, ${fmt(r.ci[1],5)}], I² ${fmt(r.I2,2)}%. Selisih JavaScript: effect ${fmt(diff,7)}, SE ${fmt(seDiff,7)}, CI max ${fmt(ciDiff,7)}. ${ciDiff<.001?'Konsisten dalam toleransi 0,001.':'Ada perbedaan, periksa τ² dan algoritme optimisasi.'}`;}catch(e){$('pythonValidation').textContent='Validasi Python belum tersedia: '+e.message+'. Jalankan backend lokal sesuai backend/README.md.'}});
 $('exportForest').addEventListener('click',()=>downloadSvg('forestPlot','ultra-paper-forest-plot.svg'));$('exportFunnel').addEventListener('click',()=>downloadSvg('funnelPlot','ultra-paper-funnel-plot.svg'));$('exportReport').addEventListener('click',txtReport);
 $('animateForest').addEventListener('click',()=>{if(!analysisCache){toast('Muat studi valid sebelum menjalankan animasi.');return}const plot=$('forestPlot');plot.classList.remove('forest-animate');void plot.offsetWidth;plot.classList.add('forest-animate');speak('Persegi adalah estimasi tiap studi, garis adalah confidence interval, dan diamond merupakan hasil gabungan meta analisis.');setTimeout(()=>plot.classList.remove('forest-animate'),5500)});
 [['pIdentified','identified'],['pDuplicates','duplicates'],['pScreenExcluded','screenExcluded'],['pNotRetrieved','notRetrieved'],['pFullExcluded','fullExcluded']].forEach(([id,key])=>$(id).addEventListener('input',e=>{project.prisma[key]=Number(e.target.value);renderPrisma()}));$('exportPrisma').addEventListener('click',exportPrisma);
 ['simA','simN1','simC','simN0'].forEach(id=>$(id).addEventListener('input',()=>{if(id==='simA'||id==='simN1'){const max=Math.max(1,Number($('simN1').value)||1);$('simRange').max=String(max);$('simRange').value=String(clamp(Number($('simA').value)||0,0,max));$('simSliderLabel').textContent=$('simRange').value}simulate()}));
 $('simRange').addEventListener('input',e=>{$('simA').value=e.target.value;$('simSliderLabel').textContent=e.target.value;simulate()});$('runSimulation').addEventListener('click',()=>{simulate();if(simResult){speak('Simulasi statistik diperbarui.');toast('Skenario diperbarui. Ini bukan prediksi klinis.')}});$('speakSimulation').addEventListener('click',()=>{if(!simResult){toast('Perbaiki input simulasi terlebih dahulu.');return}if(!('speechSynthesis' in window)){toast('Browser tidak mendukung suara.');return}const was=voice;voice=true;speak('Risiko intervensi '+fmt(simResult.r1*100,1)+' persen. Risiko kontrol '+fmt(simResult.r0*100,1)+' persen. Risk ratio '+fmt(simResult.rr)+'. Odds ratio '+fmt(simResult.or)+'.');voice=was});
 $('resetSim').addEventListener('click',()=>{Object.entries({simA:20,simN1:100,simC:35,simN0:100,simRange:20}).forEach(([id,v])=>$(id).value=v);$('simSliderLabel').textContent='20';simulate()});
 $('openEvidence').addEventListener('click',()=>showPage('evidence'));$('evidencePaper').addEventListener('change',populateEvidencePages);$('evidencePage').addEventListener('change',renderEvidencePage);$('evidenceSearch').addEventListener('click',renderEvidencePage);$('evidenceQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();renderEvidencePage()}});
 $('evidenceMatches').addEventListener('click',e=>{const b=e.target.closest('[data-jump]');if(!b)return;$('evidencePage').value=b.dataset.jump;renderEvidencePage();if(b.dataset.excerpt)$('verifiedExcerpt').value=b.dataset.excerpt});$('evidenceTables').addEventListener('click',e=>{const b=e.target.closest('[data-jump]');if(b){$('evidencePage').value=b.dataset.jump;renderEvidencePage()}});
 $('exportEvidenceCsv').addEventListener('click',()=>{const p=selectedEvidencePaper();if(!p)return toast('Pilih paper dahulu.');const rows=[['paper','page','value','source_excerpt'].map(csvCell).join(',')];buildPageCandidates(p).forEach(x=>rows.push([p.filename,x.page,x.value,x.excerpt].map(csvCell).join(',')));download('candidate-numbers.csv','\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8')});
 $('downloadEvidenceJson').addEventListener('click',exportEvidence);$('exportExtraction').addEventListener('click',()=>{showPage('evidence');exportEvidence()});
 $('createVerifiedRow').addEventListener('click',()=>{const p=selectedEvidencePaper();if(!p){toast('Pilih paper dulu.');return}const r=defaultRow((p.year?p.year+' · ':'')+p.title.slice(0,90));r.year=p.year;r.sourcePaper=p.filename;r.sourcePage=$('verifiedPage').value;r.sourceExcerpt=$('verifiedExcerpt').value.trim();r.verified=false;addStudy(r);showPage('studies');toast('Baris studi baru dibuat. Lengkapi angka dan centang Verified setelah diperiksa.')});
 $('captureBinary').addEventListener('click',()=>{const p=selectedEvidencePaper();if(!p)return toast('Pilih paper sumber');const [a,nt,c,nc]=['captureEventsT','captureTotalT','captureEventsC','captureTotalC'].map(id=>number($(id).value));if(![a,nt,c,nc].every(Number.isSafeInteger)||nt<=0||nc<=0||a<0||c<0||a>nt||c>nc)return toast('Pastikan 0 ≤ events ≤ total dan semua bilangan bulat.');if(!['RR','OR','RD'].includes(project.metric)&&project.rows.some(r=>r.include))return toast('Outcome saat ini bukan data biner. Buat proyek terpisah agar outcome tidak dicampur.');if(!['RR','OR','RD'].includes(project.metric)){project.metric='RR';$('metricSelect').value='RR'}const r=defaultRow(p.title.slice(0,95));Object.assign(r,{a:String(a),b:String(nt-a),c:String(c),d:String(nc-c),year:p.year,sourcePaper:p.filename,sourcePage:$('verifiedPage').value,sourceExcerpt:$('verifiedExcerpt').value.trim(),verified:false});addStudy(r);showPage('studies');toast('Data 2×2 ditransfer; periksa denominator, outcome, dan tandai Verified.');});
 $('captureGeneric').addEventListener('click',()=>{const p=selectedEvidencePaper();if(!p)return toast('Pilih paper sumber');const [value,low,high]=['captureRatio','captureLower','captureUpper'].map(id=>number($(id).value));if(![value,low,high].every(Number.isFinite)||low<=0||low>value||value>high||high<=low)return toast('Input 95% CI harus 0 < lower ≤ effect ≤ upper');if(project.metric!=='GEN'&&project.rows.some(r=>r.include))return toast('Jangan mencampur effect measure berbeda. Gunakan proyek terpisah dengan metric Generic.');project.metric='GEN';$('metricSelect').value='GEN';const se=(Math.log(high)-Math.log(low))/(2*1.95996398454),r=defaultRow(p.title.slice(0,90));Object.assign(r,{effect:String(Math.log(value)),se:String(se),year:p.year,sourcePaper:p.filename,sourcePage:$('verifiedPage').value,sourceExcerpt:$('verifiedExcerpt').value.trim()+` | Published ratio ${value} [${low},${high}]`,verified:false});addStudy(r);showPage('studies');toast('Published ratio dikonversi ke log effect + SE; hanya pool estimate dengan effect measure seragam.');});
 $('backendCheck').addEventListener('click',checkBackend);$('backendExtract').addEventListener('click',()=>$('backendInput').click());$('backendInput').addEventListener('change',async e=>{if(e.target.files.length)await runBackend(e.target.files);e.target.value=''});
 let saved=null;try{saved=localStorage.getItem('ultra-paper-meta-project-v1')}catch(e){}if(saved){try{restoreProject(JSON.parse(saved),true);toast('Data lokal yang sebelumnya disimpan telah dipulihkan.')}catch(e){refreshAll()}}else refreshAll();
 showPage('dashboard');
